CREATE OR REPLACE VIEW VW_GEO_PRATICHEINDIRIZZI AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE , ISTANZE.SOFTWARE AS MODULO , ISTANZE.CODICEISTANZA AS IDPRATICA , ISTANZE.NUMEROISTANZA AS NUMEROPRATICA , ISTANZE.DATA AS DATAPRATICA , VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA , VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA , VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA , STATIISTANZA.STATO AS STATOPRATICA , RICHIEDENTI.NOMINATIVO AS RICHIEDENTE_COGNOME, RICHIEDENTI.NOME AS RICHIEDENTE_NOME, RICHIEDENTI.CODICEFISCALE AS RICHIEDENTE_CODICEFISCALE, RICHIEDENTI.PARTITAIVA AS RICHIEDENTE_PARTITAIVA, TECNICI.NOMINATIVO AS TECNICO_COGNOME, TECNICI.NOME AS TECNICO_NOME, TECNICI.CODICEFISCALE AS TECNICO_CODICEFISCALE, TECNICI.PARTITAIVA AS TECNICO_PARTITAIVA, AZIENDE.NOMINATIVO AS AZIENDA_COGNOME, AZIENDE.NOME AS AZIENDA_NOME, AZIENDE.CODICEFISCALE AS AZIENDA_CODICEFISCALE, AZIENDE.PARTITAIVA AS AZIENDA_PARTITAIVA, ISTANZESTRADARIO.ID AS IDINDIRIZZO , STRADARIO.CODVIARIO AS CODVIARIO , STRADARIO.PREFISSO AS TOPONIMO , STRADARIO.DESCRIZIONE AS DESCVIA , ISTANZESTRADARIO.CODICECIVICO AS CODICECIVICO , ISTANZESTRADARIO.CIVICO AS CIVICO , ISTANZESTRADARIO.COLORE AS COLORE , ISTANZESTRADARIO.FRAZIONE AS FRAZIONE , ISTANZESTRADARIO.CIRCOSCRIZIONE AS CIRCOSCRIZIONE , ISTANZESTRADARIO.CAP AS CAP , ISTANZESTRADARIO.KM AS KM , ISTANZESTRADARIO.ESPONENTE AS ESPONENTE , ISTANZESTRADARIO.SCALA AS SCALA , ISTANZESTRADARIO.INTERNO AS INTERNO , ISTANZESTRADARIO.ESPONENTEINTERNO AS ESPONENTEINTERNO , ISTANZESTRADARIO.FABBRICATO AS FABBRICATO , ISTANZESTRADARIO.PIANO AS PIANO , ISTANZESTRADARIO.QUARTIERE AS QUARTIERE , ISTANZESTRADARIO.ID_PUNTO_SIT AS ID_PUNTO_SIT , ISTANZESTRADARIO.UUID AS UUID , ISTANZESTRADARIO.LATITUDINE AS LATITUDINE , ISTANZESTRADARIO.LONGITUDINE AS LONGITUDINE FROM ISTANZE INNER JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA INNER JOIN ANAGRAFE RICHIEDENTI ON RICHIEDENTI.IDCOMUNE = ISTANZE.IDCOMUNE AND RICHIEDENTI.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE LEFT OUTER JOIN ANAGRAFE TECNICI ON TECNICI.IDCOMUNE = ISTANZE.IDCOMUNE AND TECNICI.CODICEANAGRAFE = ISTANZE.CODICEPROFESSIONISTA LEFT OUTER JOIN ANAGRAFE AZIENDE ON AZIENDE.IDCOMUNE = ISTANZE.IDCOMUNE AND AZIENDE.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE INNER JOIN ISTANZESTRADARIO ON ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA INNER JOIN STRADARIO ON STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO;
alter table DOMANDESTC modify ULTIMOERRORE varchar(4000);
ALTER TABLE ALBEROPROC_ENDO ADD FLAG_RICHIESTO_BO NUMERIC(1,0);

ALTER TABLE TIPIMOVIMENTO ADD FLG_INVIALINKALLMAIL NUMERIC(1,0);
ALTER TABLE TIPIMOVIMENTO ADD FLG_PROTOCOLLALINKALL NUMERIC(1,0);
ALTER TABLE TIPIMOVIMENTO ADD FK_LETTTIPO_LINKALL NUMERIC(10,0);

ALTER TABLE TIPIMOVIMENTO ADD CONSTRAINT FK_TIPOMOV_LETTTIPO FOREIGN KEY (IDCOMUNE,FK_LETTTIPO_LINKALL) REFERENCES LETTERETIPO (IDCOMUNE,CODICELETTERA);

CREATE TABLE TEMP_LINKALLEGATI(
UUID VARCHAR(50) NOT NULL, 
LINK VARCHAR(500) NOT NULL, 
CODICEOGGETTO NUMERIC(10,0) NOT NULL, 
IDCOMUNE VARCHAR(6) NOT NULL, 
ID NUMERIC(10,0) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
   
CREATE UNIQUE INDEX TEMP_LINKALLEGATI_PK ON TEMP_LINKALLEGATI (IDCOMUNE, ID) ; 
ALTER TABLE TEMP_LINKALLEGATI ADD CONSTRAINT TEMP_LINKALLEGATI_PK PRIMARY KEY (IDCOMUNE, ID);

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_STATISTICHEISTANZE AS SELECT DISTINCT ISTANZE.IDCOMUNE AS f_idcomune, ISTANZE.SOFTWARE AS f_software, ISTANZE.DATA AS f_data, IFNULL(ISTANZE.codiceResponsabile, -1) AS f_responsabile, IFNULL(ISTANZE.codiceprofessionista, -1) AS f_professionista, IFNULL(ISTANZE.CODICEINTERVENTOPROC, ISTANZE.CODICEINTERVENTO) AS f_codiceintervento, IFNULL(ISTANZE.METRIQUADRATI, 0) AS f_metriquadrati, IFNULL(ISTANZE.CODICEPROCEDURA, -1) AS f_procedura, IFNULL(ISTANZEATTIVITA.CodiceAttivita, ' ') AS f_dettaglioinformazioni, IFNULL(SETTORI.CodiceSettore, -1) AS f_tipoinformazioni, IFNULL(ISTANZEAREE.CODICEAREA, -1) AS f_zonizzazione, IFNULL(AUTORIZZAZIONI.FKIDREGISTRO, -1) AS f_registro, IFNULL(ISTANZE.CHIUSURA, ' ') AS f_stato, ISTANZE.CODICEISTANZA, ISTANZE.CODICERESPONSABILE, ISTANZE.CODICERICHIEDENTE, ISTANZE.CODICEPROFESSIONISTA, ISTANZE.DATA, ISTANZE.NUMEROPROTOCOLLO, ISTANZE.DATAPROTOCOLLO, ISTANZE.CODICEINTERVENTO, ISTANZE.LAVORI, ISTANZE.CODICEPROCEDURA, ISTANZE.CODICEAREA, ISTANZE.CODICELOTTO, ISTANZE.PASSWORD, ISTANZE.ATTIVA, ISTANZE.FOGLIO, ISTANZE.PARTICELLA, ISTANZE.SUB, ISTANZE.CODICESETTORE, ISTANZE.VARIANTEPR, ISTANZE.CODICEIMPIANTO, ISTANZE.CODICEATTIVITA, ISTANZE.FLAGVIA, ISTANZE.CHIUSURA, ISTANZE.PROGREGAUT, ISTANZE.LAVORIESTESA, ISTANZE.CODICEARCHIVIO, ISTANZE.CODICESTRADARIO, ISTANZE.CIVICO, ISTANZE.AUTORIZNUMERO, ISTANZE.AUTORIZDATA, ISTANZE.AUTORIZDATAREGISTR, ISTANZE.AUTORIZRESPONSABILE, ISTANZE.TIPOMOVAVVIO, ISTANZE.TIPOARCHIVIO, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE, ISTANZE.IDMODELLO, ISTANZE.CODICEINTERVENTOPROC, ISTANZE.NUMEROISTANZA, ISTANZE.IDCOMUNE, ISTANZE.SETITOLARELEGALE, ISTANZE.FKIDTIPOLOGIAISTANZA, ISTANZE.CODICETITOLARELEGALE, ISTANZE.FKTOID, ISTANZE.METRIQUADRATI, ISTANZE.GIORNOCHIUSURA, ISTANZE.CODISTANZACOLLEGATA, ISTANZE.AZIONE, ISTANZE.FKIDREGISTRO, ISTANZE.NOMEATTIVITA, ISTANZE.FKIDFORMATO, ISTANZE.POSIZIONEARCHIVIO, ISTANZE.BASE, ISTANZE.ALTEZZA, ISTANZE.FACCE, ISTANZE.FKIDPROTOCOLLO, ISTANZE.FKCODICESOGGETTO, ISTANZE.CODICEISTRUTTORE, ISTANZE.CODICERESPONSABILEPROC, ISTANZE.CODICEAREA2, ISTANZE.FK_IDI_ATTIVITA, ISTANZE.DATAVALIDITA, ISTANZE.I_ATTIVITAORDINE, ISTANZE.CREATO_DA_STC, ISTANZE.DESCRSOGGETTO, ISTANZE.DOMICILIO_ELETTRONICO,   ISTANZE.CODICEPRATICATEL FROM ISTANZE LEFT OUTER JOIN ISTANZEATTIVITA LEFT OUTER JOIN ATTIVITA LEFT OUTER JOIN SETTORI ON ATTIVITA.IDCOMUNE=SETTORI.IDCOMUNE  AND ATTIVITA.CODICESETTORE=SETTORI.CODICESETTORE ON ISTANZEATTIVITA.IDCOMUNE=ATTIVITA.IDCOMUNE  AND ISTANZEATTIVITA.CODICEATTIVITA=ATTIVITA.CODICEISTAT ON ISTANZE.IDCOMUNE=ISTANZEATTIVITA.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEATTIVITA.CODICEISTANZA  LEFT OUTER JOIN ISTANZEAREE ON ISTANZE.IDCOMUNE=ISTANZEAREE.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEAREE.CODICEISTANZA  LEFT OUTER JOIN AUTORIZZAZIONI ON ISTANZE.IDCOMUNE=AUTORIZZAZIONI.IDCOMUNE  AND ISTANZE.CODICEISTANZA=AUTORIZZAZIONI.FKIDISTANZA;